fmt_push_int(a, 42);
fmt_push_cstr(a, "world");

char buf[256];
fmt_format_to(buf, sizeof(buf), "The answer is {} and hello {}", a);
fmt_args_free(a);
// buf == "The answer is 42 and hello world"
```

